Given an array of integers, the task is to delete a given element from the array. If there are multiple occurrences of the element, we need to remove only its first occurrence.Examples:Input: arr[] = [10, 20, 30, 40], ele = 20Output: [10, 30, 40]Input: arr[] = [10, 20, 30, 40], ele = 25Output: [10, 20, 30, 40]Input: arr[] = [10, 20, 20, 20 30], ele = 20Output: [10, 20, 20, 30]Table of Content[Approach 1] Using Built-In Methods[Approach 2] Using Custom Methods[Approach 1] Using Built-In MethodsWe will use library methods like erase() in C++, remove() in Java and Python, Remove() in C# and splice() in JavaScript.
            C++

    // C++ program to delete the first occurrence of an
// element in the array using built-in methods

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> arr = { 10, 20, 20, 20, 30 };
    int ele = 20;

    cout << "Array before deletion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

    // Find the element in the array
    auto it = find(arr.begin(), arr.end(), ele);

    // Remove the element if it is present in array
    if (it != arr.end()) {
        arr.erase(it);  
    }

    cout << "\nArray after deletion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

    return 0;
}


